import math
import numpy as np

SYMBOLS = ".abcdefghijklmnopqrstuvwxyz"


def bigram_model(words, alpha):
    N = np.zeros((27, 27))
    for w in words:
        cs = "." + w + "."
        for a, b in zip(cs, cs[1:]):
            N[SYMBOLS.index(a), SYMBOLS.index(b)] += 1
    M = N + alpha
    return M / M.sum(axis=1, keepdims=True)


def avg_nll(P, words):
    total, n = 0.0, 0
    for w in words:
        cs = "." + w + "."
        for a, b in zip(cs, cs[1:]):
            p = P[SYMBOLS.index(a), SYMBOLS.index(b)]
            if p == 0:
                return math.inf
            total -= math.log(p)
            n += 1
    return total / n

